import { html } from 'lit-html';
import { action } from '@storybook/addon-actions';

export default {
  title: 'Components/CTA Button',
  component: 'bfl-cta-button',
  tags: ['autodocs'],
  argTypes: {
    label: { control: 'text', description: 'The label of the button' },
    type: {
      control: { type: 'select' },
      options: ['outlined', 'gradient'],
      description: 'The type of the button',
    },
    isSubmit: { control: 'boolean', description: 'Whether the button is a submit button' },
  },
};

const Template = ({ label, type, isSubmit }) => html`
  <bfl-cta-button
    type=${type}
    label=${label}
    .isSubmit=${isSubmit}
    @buttonClick=${action('buttonClick')}
  ></bfl-cta-button>
`;

export const OutlinedButton = Template.bind({});
OutlinedButton.args = {
  label: 'Outlined Button',
  type: 'outlined',
  isSubmit: false,
};

export const GradientButton = Template.bind({});
GradientButton.args = {
  label: 'Gradient Button',
  type: 'gradient',
  isSubmit: false,
};

export const SubmitButton = Template.bind({});
SubmitButton.args = {
  label: 'Submit Button',
  type: 'gradient',
  isSubmit: true,
};
